1. // This Source Code Form is subject to the terms of the Mozilla Public
2. // License, v. 2.0. If a copy of the MPL was not distributed with this
3. // file, You can obtain one at https://mozilla.org/MPL/2.0/.
4. 
5. use std::path::{Path, PathBuf};
6. 
7. use ra_ap_cfg::{self as cfg};
8. use ra_ap_hir::{self as hir, AsAssocItem as _, HasAttrs as _};
9. use ra_ap_ide::{self as ide};
10. use ra_ap_ide_db::{self as ide_db};
11. use ra_ap_load_cargo::{self as load_cargo};
12. use ra_ap_paths::{self as paths};
13. use ra_ap_project_model::{self as project_model};
14. use ra_ap_syntax::{self as syntax, AstNode as _, ast};
15. use ra_ap_vfs::{self as vfs};
16. 
17. use crate::{
18.     item::{ItemCfgAttr, ItemTestAttr},
19.     options::{GeneralOptions, ProjectOptions},
20. };
21. 
22. pub struct LoadOptions {
23.     /// Analyze with `#[cfg(test)]` enabled (i.e as if built via `cargo test`).
24.     pub cfg_test: bool,
25. 
26.     /// Include sysroot crates (`std`, `core` & friends) in analysis.
27.     pub sysroot: bool,
28. }
29. 
30. pub fn load_workspace(
31.     general_options: &GeneralOptions,
32.     project_options: &ProjectOptions,
33.     load_options: &LoadOptions,
34. ) -> anyhow::Result<(hir::Crate, ide::AnalysisHost, vfs::Vfs, ide::Edition)> {
35.     let project_path = project_options.manifest_path.as_path().canonicalize()?;
36. 
37.     // See: https://github.com/rust-lang/cargo/pull/13909
38.     // The `canonicalize` func on windows will return `r"\\?\"` verbatim prefix.
39.     // "The Cargo makes a core assumption that verbatim paths aren't used."
40.     // So we need to `simplify` the path as the non-verbatim path.
41.     let project_path = dunce::simplified(&project_path).to_path_buf();
42. 
43.     let cargo_config = cargo_config(project_options, load_options);
44.     let load_config = load_config();
45. 
46.     let progress = |string| {
47.         tracing::trace!("Progress: {}", string);
48.     };
49. 
50.     let mut project_workspace = load_project_workspace(&project_path, &cargo_config, &progress)?;
51. 
52.     let (package, target) = select_package_and_target(&project_workspace, project_options)?;
53. 
54.     if general_options.verbose {
55.         eprintln!();
56.         eprintln!("crate");
57.         eprintln!("└── package: {}", package.name);
58.         eprintln!("    └── target: {}", target.name);
59.         eprintln!();
60.     }
61. 
62.     let edition = package.edition;
63. 
64.     if load_config.load_out_dirs_from_check {
65.         let build_scripts = project_workspace.run_build_scripts(&cargo_config, &progress)?;
66.         project_workspace.set_build_scripts(build_scripts)
67.     }
68. 
69.     let (db, vfs, _proc_macro_client) =
70.         ra_ap_load_cargo::load_workspace(project_workspace, &cargo_config.extra_env, &load_config)?;
71. 
72.     let host = ide::AnalysisHost::with_database(db);
73. 
74.     let krate = find_crate(host.raw_database(), &vfs, &target)?;
75. 
76.     Ok((krate, host, vfs, edition))
77. }
78. 
79. pub fn cargo_config(
80.     project_options: &ProjectOptions,
81.     load_options: &LoadOptions,
82. ) -> project_model::CargoConfig {
83.     let all_targets = false;
84. 
85.     // Crates to enable/disable `#[cfg(test)]` on
86.     let cfg_overrides = match load_options.cfg_test {
87.         true => project_model::CfgOverrides {
88.             global: cfg::CfgDiff::new(
89.                 vec![cfg::CfgAtom::Flag(hir::Symbol::intern("test"))],
90.                 Vec::new(),
91.             ),
92.             selective: Default::default(),
93.         },
94.         false => project_model::CfgOverrides {
95.             global: cfg::CfgDiff::new(
96.                 Vec::new(),
97.                 vec![cfg::CfgAtom::Flag(hir::Symbol::intern("test"))],
98.             ),
99.             selective: Default::default(),
100.         },
101.     };
102. 
103.     let extra_args = vec![];
104. 
105.     // FIXME: support extra environment variables via CLI:
106.     let extra_env = ide_db::FxHashMap::default();
107. 
108.     let extra_includes = vec![];
109. 
110.     // List of features to activate (or deactivate).
111.     let features = if project_options.all_features {
112.         project_model::CargoFeatures::All
113.     } else {
114.         project_model::CargoFeatures::Selected {
115.             features: project_options.features.clone(),
116.             no_default_features: project_options.no_default_features,
117.         }
118.     };
119. 
120.     let invocation_strategy = project_model::InvocationStrategy::PerWorkspace;
121. 
122.     let no_deps: bool = false;
123. 
124.     let run_build_script_command = None;
125. 
126.     // Rustc private crate source
127.     let rustc_source = None;
128. 
129.     let set_test = load_options.cfg_test;
130. 
131.     // Whether to load sysroot crates (`std`, `core` & friends).
132.     let sysroot = if load_options.sysroot {
133.         Some(project_model::RustLibSource::Discover)
