     pub fn is_trivially_wf(self, tcx: DbInterner<'db>) -> bool {
         match self.kind() {
             TyKind::Bool
             | TyKind::Char
             | TyKind::Int(_)
             | TyKind::Uint(_)
             | TyKind::Float(_)
             | TyKind::Str
             | TyKind::Never
             | TyKind::Param(_)
             | TyKind::Placeholder(_)
             | TyKind::Bound(..) => true,

             TyKind::Slice(ty) => {
                 ty.is_trivially_wf(tcx) && ty.has_trivial_sizedness(tcx, SizedTraitKind::Sized)
