             | TyKind::Closure(..)
             | TyKind::CoroutineClosure(..)
             | TyKind::Coroutine(..)
             | TyKind::CoroutineWitness(..)
             | TyKind::Alias(..)
             | TyKind::Error(_) => false,
         }
