526.     pub(super) fn walk_and_push_type<'db>(
527.         ty: hir::Type<'db>,
528.         db: &'db dyn HirDatabase,
529.         _edition: Edition,
530.         visit: &mut dyn FnMut(hir::ModuleDef),
531.     ) {
532.         // tracing::trace!(
533.         //     "Walking type {ty}...",
534.         //     ty = ty.display(db, edition).to_string()
535.         // );
536. 
537.         ty.walk(db, |ty| {
538.             if let Some(adt) = ty.as_adt() {
539.                 visit(adt.into());
540.             } else if let Some(trait_) = ty.as_dyn_trait() {
541.                 visit(trait_.into());
542.             } else if let Some(traits) = ty.as_impl_traits(db) {
543.                 traits.for_each(|it| visit(it.into()));
544.             } else if let Some(trait_) = ty.as_associated_type_parent_trait(db) {
545.                 visit(trait_.into());
546.             }
547.         });
